    constructor(C _c) { c = _c; }

    function run(address spender, uint256 value) public {
        require(value != 0);
        require(spender != address(0));

        bool firstApprove = c.approve(spender, value);
        uint256 allowanceAfter = c.allowance(address(this), spender);

        bool secondApprove;
        try c.approve(spender, value) returns (bool s) { secondApprove = s; } catch { secondApprove = false; }

        uint256 allowanceAfterSecond = c.allowance(address(this), spender);

        bool zeroApprove = c.approve(spender, 0);
        uint256 allowanceAfterZero = c.allowance(address(this), spender);

        assert(firstApprove && allowanceAfter == value &&
               !secondApprove && allowanceAfterSecond == value &&
               zeroApprove && allowanceAfterZero == 0);
    }
}

